# ===========================================================================
# test.jl
#
# Quick end-to-end check that the code still works, for use after changing
# it. Runs the same pipeline as 2_Interface.jl, but on a small synthetic
# population generated by GEMS and with its own small config below (it
# replaces 1_UserConfig.jl), so a run takes seconds instead of minutes.
# Results are NOT meant to be realistic; they go to the project's
# Results/test_<time> folder.
#
# The config uses most features (several categories and sections, both
# section modes, core, loyalty, cross-section contacts) so
# that a change breaking one of them shows up here.
#
# The pipeline part below copies 2_Interface.jl: keep the two in step when
# 2_Interface.jl changes.
#
# Run from the project folder: julia Concert_Project/test.jl
# ===========================================================================

ENV["GKSwstype"] = "100"   # headless plotting backend; must be set before Plots loads

import Pkg
Pkg.activate(joinpath(@__DIR__, ".."))

using GEMS, Parameters, DataFrames, Distributions, CSV,
    CategoricalArrays, JLD2, Random, StatsBase, Plots,
    StatsPlots, Dates, TOML

# === Includes (1_UserConfig.jl is replaced by the test config below) ===
include("0_Helpers.jl")
include("3_Population.jl")
include("4_Contacts.jl")
include("5_Transmission.jl")


# === Test config ===

n_simulations = 2      # more than 1, so spreads and Z-scores are exercised
run_validation = true
pop_size = 5_000       # synthetic population size

# GEMS settings: the main TOML, with a shorter simulation and more initial
# infections (the main fraction, 0.0001, would be under one person here).
# Written to a temporary file, since GEMS reads its config from a file.
config = TOML.parsefile(joinpath(@__DIR__, "config_concert_covid.toml"))
config["Simulation"]["StopCriterion"]["parameters"]["limit"] = 60
config["Simulation"]["StartCondition"]["parameters"]["fraction"] = 0.005
test_configfile = tempname() * ".toml"
open(io -> TOML.print(io, config), test_configfile, "w")

seed = config["Simulation"]["seed"]
# one stream per setup step, as in 1_UserConfig.jl, plus one for the
# synthetic population
setup_rng = Xoshiro(seed)
rng_events = Xoshiro(rand(setup_rng, UInt64))
rng_traits = Xoshiro(rand(setup_rng, UInt64))
rng_assign = Xoshiro(rand(setup_rng, UInt64))
rng_population = Xoshiro(rand(setup_rng, UInt64))
gems_seed = nothing    # or a number, to repeat a test run exactly

# transmission, as in 1_UserConfig.jl
transmission_dist = Gamma(gamma_params(0.3, 0.1)...)

# two sections, :section mode, core + loyalty + cross-section contacts
category_1 = Category(
    id = 1,
    name = "festival",
    date_range = (10, 30),
    sections = [
        Section(id=1, name="seated", n_range=(40,60), mean_contacts=4.0, std_contacts=6.0),
        Section(id=2, name="standing", n_range=(80,120), mean_contacts=8.0, std_contacts=12.0)
    ],
    n_draws = 2,
    min_age = 18,
    age_weights = [0.5, 0.35, 0.15],
    sex_weights = [0.6, 0.4],
    core = 0.1,
    loyalty = 0.2,
    cross_section_mean_contacts = 1.0,
    cross_section_std_contacts = 2.0,
    section_mode = :section
)

# one section, core + loyalty, default demographics (age_dist / sex_dist)
category_2 = Category(
    id = 2,
    name = "sport",
    date_range = (5, 40),
    sections = [
        Section(id=1, name="", n_range=(50,80), mean_contacts=6.0, std_contacts=9.0)
    ],
    n_draws = 3,
    min_age = 16,
    core = 0.2,
    loyalty = 0.3
)

# two sections, :event mode
category_3 = Category(
    id = 3,
    name = "concert",
    date_range = (15, 45),
    sections = [
        Section(id=1, name="front", n_range=(30,50), mean_contacts=10.0, std_contacts=15.0),
        Section(id=2, name="back", n_range=(60,90), mean_contacts=3.0, std_contacts=5.0)
    ],
    n_draws = 2,
    min_age = 18,
    max_age = 70,
    core = 0.1,
    loyalty = 0.2,
    cross_section_mean_contacts = 0.5,
    cross_section_std_contacts = 1.0,
    section_mode = :event
)

event_config = EventConfig(
    categories = [category_1, category_2, category_3],
    age_boundaries = [45, 65],
    age_dist = [0.211, 0.347, 0.442],
    sex_dist = [[0.420, 0.580], [0.395, 0.605], [0.426, 0.574]]
)

validate_config(event_config)


# === Run (same steps as 2_Interface.jl) ===

events = sample_events(event_config, rng_events)
sort!(events, by = e -> (e.date, e.category_id, e.draw_id, e.section_id))

println("\n=== Sampled Events ===")
for e in events
    println("Event $(e.id) ($(e.name)) — date: $(e.date), n: $(e.n), contacts: $(e.mean_contacts)")
end

sim_length = config["Simulation"]["StopCriterion"]["parameters"]["limit"]
last_day = sim_length - 1   # GEMS simulates days 0 to limit - 1

for e in events
    if e.date > last_day
        @warn "Event $(e.id) on day $(e.date) is after the last simulated day ($last_day; " *
              "GEMS simulates days 0 to StopCriterion limit - 1). Results will be inaccurate."
    end
end

# synthetic population: GEMS generates households, offices and school
# classes with realistic ages (no municipalities)
synthetic = dataframe(Population(n = pop_size, rng = rng_population))
people, age_groups, sex_levels = prepare_population(event_config, rng_traits, synthetic, transmission_dist)
attendees, core_groups = assign_events!(people, events, event_config, rng_assign)

transmission_func = SettingRate(
    event_dates = Set{Int16}(Int16(e.date) for e in events)
)

b = Batch(
    n_runs = n_simulations,
    configfile = test_configfile,
    population = people,
    ind_extension = GEMS_COLUMNS,   # defined once, in 3_Population.jl
    transmission_function = transmission_func,
    label = "Test simulation",
    setup = sim -> daily_global_setting!(sim, sum(length, people.event_dates))
)

isnothing(gems_seed) || gems_seed isa Integer ||
    error("gems_seed in test.jl must be nothing or an integer, got $(repr(gems_seed)).")
gems_seed_used = isnothing(gems_seed) ? rand(RandomDevice(), 0:typemax(Int64)) : Int64(gems_seed)
println("\nGEMS seed: $gems_seed_used, $(Threads.nthreads()) thread(s).")

bd = BatchData(b; rd_style = "EssentialResultData", seed = gems_seed_used)

event_results = Vector{Dict{String,EventCounts}}()
for rd in runs(bd)
    push!(event_results, analyze_event_population(infections(rd), people, events, attendees))
end

aggregated = aggregate_event_results(event_results)

# always the project's Results folder, wherever Julia was started from
run_folder = normpath(joinpath(@__DIR__, "..", "Results",
    "test_$(n_simulations)sims_$(Dates.format(Dates.now(), "yyyy-mm-dd_HH-MM-SS"))"))
mkpath(run_folder)

# everything needed to rerun this test run (test.jl holds its own config)
save_run_info(run_folder,
    [joinpath(@__DIR__, f) for f in ("test.jl", "config_concert_covid.toml")];
    n_simulations, run_validation, pop_size,
    setup_seed = seed, gems_seed = gems_seed_used)
save_raw_results(run_folder, events, event_results, attendees, core_groups, people)

println("\nSimulation complete.")
include("6_Analysis.jl")

if run_validation
    validation_file = joinpath(run_folder, "validation.txt")
    open(validation_file, "w") do io
        redirect_stdout(() -> include("7_Validation.jl"), io)
    end
    print(read(validation_file, String))
    println("Saved: validation")
end

rm(test_configfile; force=true)
println("End test")
